{
  "title": "agent.completions.message.MessageExpression",
  "description": "A message with expressions for dynamic content.\n\nThis is the expression variant of [`Message`] used in function definitions\nwhere message content can be computed from the function input at runtime.\nSupports both JMESPath and Starlark expressions.",
  "anyOf": [
    {
      "title": "Developer",
      "type": "object",
      "$ref": "agent.completions.message.DeveloperMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "developer"
          ]
        }
      }
    },
    {
      "title": "System",
      "type": "object",
      "$ref": "agent.completions.message.SystemMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "system"
          ]
        }
      }
    },
    {
      "title": "User",
      "type": "object",
      "$ref": "agent.completions.message.UserMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "user"
          ]
        }
      }
    },
    {
      "title": "Assistant",
      "type": "object",
      "$ref": "agent.completions.message.AssistantMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "assistant"
          ]
        }
      }
    },
    {
      "title": "Tool",
      "type": "object",
      "$ref": "agent.completions.message.ToolMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "tool"
          ]
        }
      }
    }
  ]
}

{
  "title": "agent.completions.message.ImageUrlDetail",
  "description": "Detail level for image processing.",
  "anyOf": [
    {
      "title": "Auto",
      "description": "Let the model decide the detail level.",
      "type": "string",
      "enum": [
        "auto"
      ]
    },
    {
      "title": "Low",
      "description": "Low detail mode (faster, less tokens).",
      "type": "string",
      "enum": [
        "low"
      ]
    },
    {
      "title": "High",
      "description": "High detail mode (more accurate, more tokens).",
      "type": "string",
      "enum": [
        "high"
      ]
    }
  ]
}

